<?php
declare(strict_types=1);
$root=dirname(__DIR__);$storage=$root.'/storage';$configDir=$root.'/config';$installed=is_file($storage.'/installed.lock');$error='';$success='';
function cleanUrl(string $url): string {$url=rtrim(trim($url),'/');if(!$url||!filter_var($url,FILTER_VALIDATE_URL)||!in_array(parse_url($url,PHP_URL_SCHEME),['http','https'],true)||parse_url($url,PHP_URL_QUERY)||parse_url($url,PHP_URL_FRAGMENT))throw new RuntimeException('URL base inválida.');return $url;}
if(!$installed&&($_SERVER['REQUEST_METHOD']??'GET')==='POST'){try{$base=cleanUrl((string)($_POST['base_url']??''));$dbHost=trim((string)($_POST['db_host']??'localhost'));$dbPort=(int)($_POST['db_port']??3306);$dbName=trim((string)($_POST['db_name']??''));$dbUser=trim((string)($_POST['db_user']??''));$dbPass=(string)($_POST['db_password']??'');$adminName=trim((string)($_POST['admin_name']??''));$adminEmail=strtolower(trim((string)($_POST['admin_email']??'')));$adminPass=(string)($_POST['admin_password']??'');if(!preg_match('/^[a-zA-Z0-9_.-]+$/',$dbName)||!$dbUser)throw new RuntimeException('Informe o banco, usuário e senha do MySQL.');if($dbPort<1||$dbPort>65535)throw new RuntimeException('Porta do banco inválida.');if(mb_strlen($adminName)<2||mb_strlen($adminName)>150)throw new RuntimeException('Informe seu nome.');if(!filter_var($adminEmail,FILTER_VALIDATE_EMAIL))throw new RuntimeException('E-mail administrativo inválido.');if(strlen($adminPass)<10)throw new RuntimeException('A senha deve ter pelo menos 10 caracteres.');if(!is_dir($configDir))mkdir($configDir,0700,true);foreach([$storage,$storage.'/uploads',$storage.'/logs',$storage.'/cache',$storage.'/sessions'] as $dir)if(!is_dir($dir))mkdir($dir,0700,true);
  $cfg=['base_url'=>$base,'timezone'=>'America/Fortaleza','db'=>['host'=>$dbHost,'port'=>$dbPort,'name'=>$dbName,'user'=>$dbUser,'password'=>$dbPass],'app_key'=>bin2hex(random_bytes(32)),'cron_key'=>bin2hex(random_bytes(24)),'google_client_id'=>'','google_client_secret'=>'','smtp'=>['host'=>'','port'=>587,'encryption'=>'tls','username'=>'','password'=>'','from'=>'','from_name'=>'TaskEsc'],'trusted_origins'=>['https://chatgpt.com','https://chat.openai.com']];$tmp=$configDir.'/config.php.tmp';file_put_contents($tmp,"<?php\nreturn ".var_export($cfg,true).";\n",LOCK_EX);chmod($tmp,0600);rename($tmp,$configDir.'/config.php');
  $pdo=new PDO("mysql:host=$dbHost;port=$dbPort;charset=utf8mb4",$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>true]);$pdo->exec('CREATE DATABASE IF NOT EXISTS `'.$dbName.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$pdo->exec('USE `'.$dbName.'`');$sql=file_get_contents($root.'/database/schema.sql');$pdo->exec($sql);$st=$pdo->prepare('INSERT INTO users (name,email,password_hash,role,active,created_at) VALUES (?,?,?,?,1,UTC_TIMESTAMP())');$st->execute([$adminName,$adminEmail,password_hash($adminPass,PASSWORD_DEFAULT),'admin']);file_put_contents($storage.'/installed.lock',gmdate('c').'\n',LOCK_EX);chmod($storage.'/installed.lock',0600);$success='Instalação concluída. Entre com seu usuário administrativo.';$installed=true;}catch(Throwable $e){$error=$e->getMessage();@unlink($configDir.'/config.php.tmp');}}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Instalação · TaskEsc</title><style>body{margin:0;background:#050505;color:#f5f5f5;font:16px system-ui;display:grid;place-items:center;min-height:100vh}.box{width:min(680px,92vw);background:#0e0e0e;border:1px solid #2b2b2b;border-radius:22px;padding:32px;box-shadow:0 24px 80px #020617aa}h1{margin:0 0 8px}p{color:#a3a3a3;line-height:1.5}label{display:block;margin:14px 0 5px;color:#d4d4d4}input{box-sizing:border-box;width:100%;padding:12px;border:1px solid #333;border-radius:9px;background:#151515;color:#fff;font-size:15px}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.msg{padding:12px 14px;border-radius:10px;margin:16px 0}.error{background:#7f1d1d;color:#fecaca}.ok{background:#14532d;color:#bbf7d0}button{margin-top:20px;padding:13px 22px;border:0;border-radius:9px;background:#fff;color:#050505;font-weight:700;cursor:pointer}</style><link rel="stylesheet" href="assets/taskesc-theme.css?v=<?= (int)filemtime(__DIR__.'/assets/taskesc-theme.css') ?>"></head><body class="install-page"><main class="box"><h1>TaskEsc</h1><p>Instalação do sistema de gestão audiovisual em PHP + MySQL para hospedagem Apache.</p><?php if($error):?><div class="msg error"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;if($success):?><div class="msg ok"><?=htmlspecialchars($success,ENT_QUOTES,'UTF-8')?> <a style="color:#bbf7d0" href="index.php">Abrir sistema</a></div><?php elseif(!$installed):?><form method="post"><label>URL do sistema<input name="base_url" required placeholder="https://task.seudominio.com"></label><div class="row"><div><label>Host MySQL<input name="db_host" value="localhost" required></label></div><div><label>Porta<input name="db_port" value="3306" inputmode="numeric" required></label></div></div><div class="row"><div><label>Banco<input name="db_name" placeholder="taskesc" required></label></div><div><label>Usuário MySQL<input name="db_user" required></label></div></div><label>Senha MySQL<input name="db_password" type="password"></label><hr style="border-color:#2b2b2b;margin:24px 0"><label>Seu nome<input name="admin_name" required></label><label>Seu e-mail<input name="admin_email" type="email" required></label><label>Senha administrativa (mínimo 10 caracteres)<input name="admin_password" type="password" minlength="10" required></label><button>Instalar sistema</button></form><?php else:?><div class="msg error">O sistema já foi instalado. Remova <code>storage/installed.lock</code> somente se precisar reinstalar.</div><?php endif;?></main></body></html>
